import{isEveDevEnvironment}from"#internal/application/dev-environment.js";import{shutdownActiveSandboxConnections}from"#execution/sandbox/active-connections.js";function shouldInstallSandboxShutdown(e){return!(isEveDevEnvironment()||e.EVE_DEVELOPMENT_SANDBOX_RUN_ID!==void 0||e.VERCEL!==void 0)}async function runSandboxShutdown(e){let t,n=new Promise(n=>{t=setTimeout(()=>{e(`eve: sandbox shutdown timed out; continuing exit`),n()},15e3),t.unref?.()});try{await Promise.race([shutdownActiveSandboxConnections({log:e}),n])}finally{clearTimeout(t)}}function installSandboxShutdown(e){shouldInstallSandboxShutdown(e.env)&&e.nitroApp?.hooks?.hook(`close`,async()=>{await runSandboxShutdown(e.log)})}function sandboxShutdownPlugin(e){installSandboxShutdown({env:process.env,log:e=>console.error(e),nitroApp:e})}export{sandboxShutdownPlugin as default,installSandboxShutdown,runSandboxShutdown,shouldInstallSandboxShutdown};